// ── Extrair e validar payload do ModernPOS ─────────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const lojaId       = body.loja_id ?? 0;
const instanceName = body.instance_name ?? '';
const event        = body.event ?? '';
const receivedAt   = body.received_at ?? new Date().toISOString();

// Mensagem do cliente
const inbound      = body.inbound ?? {};
const remoteJid    = inbound.remoteJid ?? '';
const pushName     = inbound.pushName  ?? 'Cliente';
const messageType  = inbound.messageType ?? 'text';
const messageText  = inbound.messageText ?? '';

// Contexto fornecido pelo ModernPOS
const consulta       = body.consulta ?? {};
const customerMemory = consulta.ia_customer_memory ?? null;
const catalogVariants= consulta.ia_catalog_variants ?? [];
const atendimento    = consulta.ia_status_atendimento ?? { status: 'Ativo' };

// Construir contexto de catálogo para o prompt
let catalogContext = '';
if (catalogVariants.length > 0) {
  catalogContext = '\n\n📦 PRODUTOS DISPONÍVEIS NO ESTOQUE (relevantes à mensagem):\n';
  catalogVariants.forEach((v, i) => {
    catalogContext += `${i + 1}. ${v.product_name} — Cor: ${v.color ?? '?'}, Tam: ${v.size ?? '?'}, R$ ${Number(v.price).toFixed(2)}, Estoque: ${v.stock_qty} un.\n`;
  });
} else {
  catalogContext = '\n\n⚠️ Nenhum produto encontrado para a busca atual. Sugira alternativas disponíveis ou peça mais detalhes.';
}

// Construir histórico / memória do cliente
let customerContext = '';
if (customerMemory) {
  const prefs = customerMemory.preferences ?? {};
  customerContext = `\n\n👤 PERFIL DA CLIENTE:\n`;
  customerContext += `- Nome: ${customerMemory.pushName ?? pushName}\n`;
  if (customerMemory.usual_size) customerContext += `- Tamanho habitual: ${customerMemory.usual_size}\n`;
  if (prefs.cores?.length)    customerContext += `- Cores favoritas: ${prefs.cores.join(', ')}\n`;
  if (prefs.estilos?.length)  customerContext += `- Estilos favoritos: ${prefs.estilos.join(', ')}\n`;
  customerContext += `- Total de interações: ${customerMemory.total_interactions ?? 0}\n`;
}

return [{
  json: {
    lojaId, instanceName, event, receivedAt,
    remoteJid, pushName, messageType, messageText,
    catalogContext, customerContext,
    catalogVariants, customerMemory, atendimento,
    rawBody: body
  }
}];

// ── Montar mensagens para a OpenAI ────────────────────────────────────────
const d = $input.first().json;

const systemPrompt = `Você é a assistente virtual da loja de moda. Seu nome é Sofia.
Você é especialista em moda feminina e conhece cada peça do catálogo.
Seja calorosa, consultiva e use emojis com moderação.

REGRAS IMPORTANTES:
- Nunca invente preços ou disponibilidade — use apenas os dados do estoque fornecidos.
- Se uma peça estiver esgotada, sugira imediatamente uma alternativa similar.
- Lembre das preferências da cliente e use-as nas sugestões.
- Ao fechar pedido, confirme os itens antes de gerar qualquer link.
- Máximo de 3 produtos por mensagem.
- Use linguagem natural e feminina, como uma amiga consultiva.
- Para pedidos, instrua a cliente a confirmar respondendo com OK.
${d.customerContext}${d.catalogContext}`;

return [{
  json: {
    ...d,
    messages: [
      { role: "system",  content: systemPrompt },
      { role: "user",    content: d.messageText }
    ]
  }
}];

// ── Extrair resposta da OpenAI e formatar para o ModernPOS ─────────────────
const d        = $input.first().json;
const aiResult = d.choices?.[0]?.message?.content ?? '';
const text     = aiResult.trim();

// Detectar se a resposta inclui uma imagem (formato especial: [IMG:url])
const imgMatch = text.match(/\[IMG:(https?:\/\/[^\]]+)\]/);

if (imgMatch) {
  const mediaUrl = imgMatch[1];
  const caption  = text.replace(imgMatch[0], '').trim();
  return [{
    json: {
      replyType:  'media',
      mediatype:  'image',
      mimetype:   'image/jpeg',
      media:      mediaUrl,
      caption:    caption || text,
      fileName:   'produto.jpg',
      _debug: { lojaId: d.lojaId, remoteJid: d.remoteJid, aiRaw: text }
    }
  }];
}

return [{
  json: {
    replyType: 'text',
    text:      text,
    _debug: { lojaId: d.lojaId, remoteJid: d.remoteJid, tokensUsed: d.usage?.total_tokens ?? 0 }
  }
}];
